'use client';
import { type ReactNode, useRef, useState } from 'react';
import { motion, useInView, type Variant, type Transition, type UseInViewOptions } from 'motion/react';

export type InViewProps = {
  children: ReactNode;
  variants?: {
    hidden: Variant;
    visible: Variant;
  };
  transition?: Transition;
  viewOptions?: UseInViewOptions;
  as?: React.ElementType;
  once?: boolean
};

const defaultVariants = {
  hidden: { opacity: 0 },
  visible: { opacity: 1 },
};

export function InView({
  children,
  variants = defaultVariants,
  transition,
  viewOptions,
  as = 'div',
  once
}: InViewProps) {
  const ref = useRef(null);
  const isInView = useInView(ref, viewOptions);

  const [isViewed, setIsViewed] = useState(false)

  const MotionComponent = motion[as as keyof typeof motion] as typeof as;

  return (
    <MotionComponent
      ref={ref}
      initial='hidden'
      onAnimationComplete={() => {
        if (once) setIsViewed(true)
      }}
      animate={(isInView || isViewed) ? "visible" : "hidden"}

      variants={variants}
      transition={transition}
    >
      {children}
    </MotionComponent>
  );
}

import * as React from "react"
import { motion, useReducedMotion } from "motion/react"
import { InView } from "@/components/primitives/in-view"
import { SectionHead, SectionShell } from "@/components/primitives/handcraft"
import { cn } from "@/lib/utils"

// The layer components — head, meta band, module rows (repeat), base.
import { CourseHead } from "./layers/CourseHead"
import { CourseMeta } from "./layers/CourseMeta"
import { CourseModule } from "./layers/CourseModule"
import { CourseBase } from "./layers/CourseBase"

// ═══ JOB         Show the whole path before asking for the enroll.
// ═══ EMOTION     A trail you can already see yourself walking.
// ═══ SIGNATURE   The modules are the fillings: done/active/locked states
//                 read at a glance, rows stagger in like a syllabus being
//                 dealt. Head, meta, modules and base are separate imports.

export type CourseModuleDef = {
  title: string
  lessons?: number
  duration?: string
  state?: "done" | "active" | "locked"
}

export type StackCourseProps = {
  eyebrow?: string
  title?: React.ReactNode
  subtitle?: React.ReactNode
  head?: { title: string; instructor?: string; level?: string }
  meta?: { modules?: string; lessons?: string; duration?: string }
  modules?: CourseModuleDef[]
  price?: string
  cta?: string
  caption?: string
  tone?: "paper" | "ink"
  className?: string
}

export function StackCourse({
  eyebrow = "STACK · COURSE",
  title = "The syllabus, dealt open.",
  subtitle = "Course band, meta strip, module rows and enroll base are separate components — modules repeat like fillings with done / active / locked states.",
  head = { title: "Booking Boards That Don't Lie", instructor: "Klara Lindqvist", level: "Beginner friendly" },
  meta = { modules: "6 modules", lessons: "24 lessons", duration: "4 h 20 m" },
  modules = [
    { title: "What a board owes the floor", lessons: 4, duration: "38 min", state: "done" },
    { title: "Time you can actually sell", lessons: 5, duration: "52 min", state: "active" },
    { title: "Chairs, mirrors and truth", lessons: 4, duration: "41 min", state: "locked" },
    { title: "Reminders people answer", lessons: 4, duration: "44 min", state: "locked" },
    { title: "The no-show autopsy", lessons: 4, duration: "47 min", state: "locked" },
    { title: "Ship your board", lessons: 3, duration: "38 min", state: "locked" },
  ],
  price = "1 490 kr",
  cta = "Enroll now",
  caption = "FOUR LAYER COMPONENTS · REPEATABLE MODULES",
  tone = "paper",
  className,
}: StackCourseProps) {
  const ink = tone === "ink"
  const reduce = useReducedMotion()

  return (
    <SectionShell tone={tone} width={920} rule="bottom" className={className}>
      <InView
        once
        variants={{ hidden: { opacity: 0, y: 14 }, visible: { opacity: 1, y: 0 } }}
        transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1] }}
      >
        <SectionHead eyebrow={eyebrow} title={title} subtitle={subtitle} tone={tone} />
      </InView>

      <InView
        once
        variants={{ hidden: { opacity: 0, y: 24 }, visible: { opacity: 1, y: 0 } }}
        transition={{ duration: 0.9, ease: [0.16, 1, 0.3, 1], delay: 0.1 }}
      >
        <figure className="mt-10">
          <div className="mx-auto max-w-[520px]">
            <div
              className={cn(
                "overflow-hidden rounded-[18px] border bg-card shadow-[0_26px_56px_-30px_hsl(var(--foreground)/0.45)]",
                ink ? "border-background/15" : "border-border",
              )}
            >
              <CourseHead title={head.title} instructor={head.instructor} level={head.level} />
              <CourseMeta modules={meta.modules} lessons={meta.lessons} duration={meta.duration} />

              <div role="list" aria-label="Course modules">
                {modules.map((m, i) => (
                  <motion.div
                    key={m.title}
                    role="listitem"
                    initial={reduce ? { opacity: 0 } : { opacity: 0, x: -16 }}
                    whileInView={{ opacity: 1, x: 0 }}
                    viewport={{ once: true }}
                    transition={{ duration: 0.45, ease: [0.16, 1, 0.3, 1], delay: 0.25 + i * 0.07 }}
                  >
                    <CourseModule index={i + 1} title={m.title} lessons={m.lessons} duration={m.duration} state={m.state} />
                  </motion.div>
                ))}
              </div>

              <motion.div
                initial={reduce ? { opacity: 0 } : { opacity: 0, y: 12 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ duration: 0.5, ease: [0.16, 1, 0.3, 1], delay: 0.6 }}
              >
                <CourseBase price={price} cta={cta} />
              </motion.div>
            </div>
          </div>

          {caption && (
            <figcaption
              className={cn(
                "mx-auto mt-8 flex max-w-[520px] items-center justify-between border-t pt-3 font-mono text-[10px] font-bold uppercase tracking-[0.3em]",
                ink ? "border-background/15 text-background/55" : "border-border text-muted-foreground",
              )}
            >
              <span>{caption}</span>
              <span aria-hidden>●</span>
            </figcaption>
          )}
        </figure>
      </InView>
    </SectionShell>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

// ── COURSE BASE — the bottom bun. Enroll CTA + price. ───────────────────────

export type CourseBaseProps = {
  cta?: string
  price?: string
  onEnroll?: () => void
  note?: string
  className?: string
}

export function CourseBase({ cta = "Enroll now", price = "1 490 kr", onEnroll, note = "Lifetime access · 14-day guarantee", className }: CourseBaseProps) {
  return (
    <div className={cn("flex items-center gap-3 rounded-b-[16px] border-t border-border/60 bg-muted/40 px-5 py-4", className)}>
      <span className="font-display text-[19px] font-black tabular-nums">{price}</span>
      <button
        type="button"
        onClick={onEnroll}
        className="ml-auto h-10 rounded-full bg-foreground px-5 text-[11px] font-black uppercase tracking-[0.14em] text-background transition-transform hover:-translate-y-0.5 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
      >
        {cta}
      </button>
      <span className="sr-only">{note}</span>
      <span aria-hidden className="font-mono text-[9px] font-bold uppercase tracking-[0.14em] text-muted-foreground">{note}</span>
    </div>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

// ── COURSE HEAD — the upper bun. Course + instructor band. ──────────────────

export type CourseHeadProps = {
  title: string
  instructor?: string
  level?: string
  className?: string
}

export function CourseHead({ title, instructor = "Klara Lindqvist", level = "Beginner friendly", className }: CourseHeadProps) {
  return (
    <div className={cn("rounded-t-[16px] bg-foreground px-5 py-4 text-background", className)}>
      <p className="font-mono text-[9px] font-bold uppercase tracking-[0.24em] opacity-60">{level} · taught by {instructor}</p>
      <h3 className="mt-1 font-display text-[19px] font-extrabold leading-snug tracking-tight">{title}</h3>
    </div>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

// ── COURSE META — the honest-numbers band. ──────────────────────────────────

export type CourseMetaProps = {
  modules?: string
  lessons?: string
  duration?: string
  className?: string
}

export function CourseMeta({ modules = "6 modules", lessons = "24 lessons", duration = "4 h 20 m", className }: CourseMetaProps) {
  const cells = [modules, lessons, duration]
  return (
    <div className={cn("grid grid-cols-3 divide-x divide-border/60 border-b border-border/60", className)}>
      {cells.map((c) => (
        <span key={c} className="px-4 py-3 text-center font-mono text-[10px] font-bold uppercase tracking-[0.16em] text-muted-foreground">
          {c}
        </span>
      ))}
    </div>
  )
}

import * as React from "react"
import { Check, Lock, PlayCircle } from "lucide-react"
import { cn } from "@/lib/utils"

// ── COURSE MODULE — one module row. The filling: repeat one per module. ─────

export type CourseModuleProps = {
  index: number
  title: string
  lessons?: number
  duration?: string
  state?: "done" | "active" | "locked"
  className?: string
}

export function CourseModule({ index, title, lessons = 4, duration = "42 min", state = "locked", className }: CourseModuleProps) {
  const mark =
    state === "done" ? (
      <Check className="size-3.5" strokeWidth={3} aria-hidden />
    ) : state === "active" ? (
      <PlayCircle className="size-3.5" aria-hidden />
    ) : (
      <Lock className="size-3" aria-hidden />
    )
  return (
    <div
      className={cn(
        "flex items-center gap-3.5 border-t border-border/50 px-5 py-3.5 first:border-t-0",
        state === "active" && "bg-primary/[0.05]",
        className,
      )}
    >
      <span
        aria-hidden
        className={cn(
          "flex size-7 shrink-0 items-center justify-center rounded-full border font-mono text-[10px] font-black tabular-nums",
          state === "done" && "border-primary bg-primary text-primary-foreground",
          state === "active" && "border-primary text-primary",
          state === "locked" && "border-border text-muted-foreground",
        )}
      >
        {mark}
      </span>
      <span className="min-w-0 flex-1">
        <span className={cn("block truncate text-[13px] font-bold", state === "locked" && "text-muted-foreground")}>{title}</span>
        <span className="block font-mono text-[9px] font-bold uppercase tracking-[0.16em] text-muted-foreground">
          module {String(index).padStart(2, "0")} · {lessons} lessons · {duration}
        </span>
      </span>
    </div>
  )
}
